let s = context.get('stats') || {n:0, tMin:999, tMax:-999, tSum:0, hMin:999, hMax:-999, hSum:0, pMin:9999, pMax:0, pSum:0};
const d = msg.payload;
s.n++;
s.tMin = Math.min(s.tMin, d.temperature); s.tMax = Math.max(s.tMax, d.temperature); s.tSum += d.temperature;
s.hMin = Math.min(s.hMin, d.humidity); s.hMax = Math.max(s.hMax, d.humidity); s.hSum += d.humidity;
s.pMin = Math.min(s.pMin, d.pressure); s.pMax = Math.max(s.pMax, d.pressure); s.pSum += d.pressure;
context.set('stats', s);
msg.payload = {
  temperature: {min: s.tMin, max: s.tMax, avg: +(s.tSum/s.n).toFixed(2)},
  humidity: {min: s.hMin, max: s.hMax, avg: +(s.hSum/s.n).toFixed(2)},
  pressure: {min: s.pMin, max: s.pMax, avg: +(s.pSum/s.n).toFixed(2)}
};
return msg;
